@Component({ selector: "app-paginator", templateUrl: "./paginator.component.html",
  changeDetection: ChangeDetectionStrategy.OnPush })
export class PaginatorComponent implements OnChanges {
  @Input() totalItems = 0; @Input() pageSize = 10; @Input() currentPage = 1;
  @Output() pageChange = new EventEmitter<number>();
  totalPages = 0;
  ngOnChanges(changes: SimpleChanges): void {
    if (changes["totalItems"] || changes["pageSize"])
      this.totalPages = Math.ceil(this.totalItems/this.pageSize); }
  goTo(page: number): void {
    if (page >= 1 && page <= this.totalPages) this.pageChange.emit(page); } }

@Directive({ selector: "[appHighlight]" })
export class HighlightDirective {
  @Input("appHighlight") color = "yellow";
  constructor(private readonly el: ElementRef<HTMLElement>,
              private readonly renderer: Renderer2) {}
  @HostListener("mouseenter") onEnter(): void {
    this.renderer.setStyle(this.el.nativeElement,"backgroundColor",this.color); }
  @HostListener("mouseleave") onLeave(): void {
    this.renderer.removeStyle(this.el.nativeElement,"backgroundColor"); } }

const results$ = this.searchInput.valueChanges.pipe(
  debounceTime(300), distinctUntilChanged(),
  filter(term => (term?.length ?? 0) >= 2),
  switchMap(term => this.searchService.search(term).pipe(
    catchError(() => of([])))));

