    <h2>{{ user.displayName }}</h2><p>{{ user.email }}</p>
    <button (click)="onSelect()">Select</button></div>`,
  changeDetection: ChangeDetectionStrategy.OnPush })
export class UserCardComponent {
  @Input() user!: UserProfile;
  @Input() isHighlighted = false;
  @Output() selected = new EventEmitter<UserProfile>();
  onSelect(): void { this.selected.emit(this.user); } }

this.profileForm = this.fb.group({
  displayName: ["", [Validators.required, Validators.maxLength(100)]],
  email:       ["", [Validators.required, Validators.email]],
  bio:         ["", Validators.maxLength(500)],
  website:     ["", Validators.pattern(/^https?:\/\/.+/)]
}, { validators: this.atLeastOneContactValidator });

@Pipe({ name: "truncate", pure: true })
export class TruncatePipe implements PipeTransform {
  transform(value: string|null|undefined, limit=100, ellipsis="Ã¢ÂÂ¦"): string {
    if (!value) return "";
    if (value.length <= limit) return value;
    const truncated = value.slice(0,limit).trimEnd();
    return truncated+ellipsis; } }

const merged$ = combineLatest([
  this.userService.currentUser$,
  this.permissionService.permissions$,
  this.featureService.flags$
]).pipe(
  map(([user,permissions,flags]) => ({
    canEdit:   permissions.includes("EDIT")   && flags.editorEnabled,
    canDelete: permissions.includes("DELETE") && user.role === "admin",
    userName:  user.displayName
  })), shareReplay(1));

@Injectable({ providedIn: "root" })
export class AuthService {
  private readonly _user$ = new BehaviorSubject<User|null>(null);
  readonly currentUser$ = this._user$.asObservable();
  constructor(private readonly http: HttpClient) {}
  login(creds: LoginCredentials): Observable<void> {
    return this.http.post<AuthResponse>("/api/auth/login", creds).pipe(
      tap(r => this._user$.next(r.user)), map(() => void 0)); }
  logout(): void { this._user$.next(null); } }

const routes: Routes = [
  { path: "", redirectTo: "dashboard", pathMatch: "full" },
  { path: "dashboard", component: DashboardComponent },
  { path: "admin", canActivate: [AuthGuard, RoleGuard],
    data: { requiredRole: "admin" },
    loadChildren: () => import("./admin/admin.module").then(m => m.AdminModule) },
  { path: "**", component: NotFoundComponent }
];

